    "grammar-flashcards": {
      "title": "Lesson 40 Grammar Flashcards",
      "cards": [
        {
          "prompt": "φησὶ τὸν ἄνδρα λέγειν.",
          "answer": "He says that the man is speaking; simultaneous. — 1. Infinitive reports and relative time"
        },
        {
          "prompt": "φησὶ τὸν ἄνδρα εἰπεῖν.",
          "answer": "He says that the man spoke; prior. — 1. Infinitive reports and relative time"
        },
        {
          "prompt": "φησὶ τὸν ἄνδρα ἐρεῖν.",
          "answer": "He says that the man will speak; later. — 1. Infinitive reports and relative time"
        },
        {
          "prompt": "φησὶ δίκαιος εἶναι.",
          "answer": "He says that he himself is just; shared subject. — 1. Infinitive reports and relative time"
        },
        {
          "prompt": "φησὶ τὸν ἄνδρα εἰρηκέναι.",
          "answer": "He says that the man has spoken; perfect result/relevance. — 1. Infinitive reports and relative time"
        },
        {
          "prompt": "ὁρῶ τὸν δῆμον ὀργιζόμενον.",
          "answer": "I see the people becoming angry; supplementary participle. — 2. Perception participles and finite reports"
        },
        {
          "prompt": "λέγει ὅτι χειμὼν ἐκώλυσεν.",
          "answer": "He says that a storm prevented it; finite report. — 2. Perception participles and finite reports"
        },
        {
          "prompt": "ὁρῶ τὸν ἄνδρα ἐλθόντα.",
          "answer": "I see that the man has arrived; aorist participle. — 2. Perception participles and finite reports"
        },
        {
          "prompt": "ἀκούω τὸν ἄνδρα λέγοντα.",
          "answer": "I hear the man speaking; perceived action. — 2. Perception participles and finite reports"
        },
        {
          "prompt": "ὀργιζόμενον agrees with τὸν δῆμον",
          "answer": "accusative masculine singular — 2. Perception participles and finite reports"
        },
        {
          "prompt": "φησί(ν)",
          "answer": "he or she says; present third singular — 3. φημί and negation"
        },
        {
          "prompt": "φασί(ν)",
          "answer": "they say; present third plural — 3. φημί and negation"
        },
        {
          "prompt": "ἔφησθα",
          "answer": "you said; imperfect second singular — 3. φημί and negation"
        },
        {
          "prompt": "ἔφασαν",
          "answer": "they said; imperfect third plural — 3. φημί and negation"
        },
        {
          "prompt": "φημί / φῄς / φησί / φαμέν / φατέ / φασί",
          "answer": "present indicative paradigm — 3. φημί and negation"
        },
        {
          "prompt": "ἔφην / ἔφησθα / ἔφη / ἔφαμεν / ἔφατε / ἔφασαν",
          "answer": "imperfect paradigm — 3. φημί and negation"
        },
        {
          "prompt": "τὸ ἀκούειν",
          "answer": "listening; nominative or accusative articular infinitive — 4. The articular infinitive"
        },
        {
          "prompt": "τοῦ ἀκούειν",
          "answer": "of listening; genitive articular infinitive — 4. The articular infinitive"
        },
        {
          "prompt": "τῷ ἀκούειν",
          "answer": "by/in listening; dative articular infinitive — 4. The articular infinitive"
        },
        {
          "prompt": "πρὸ τοῦ τὴν βουλὴν κρῖναι",
          "answer": "before the council judges; accusative subject within genitive phrase — 4. The articular infinitive"
        },
        {
          "prompt": "τὸ χωρὶς ἕκαστον κρίνειν",
          "answer": "trying each person separately — 4. The articular infinitive"
        },
        {
          "prompt": "ὃ λέγει",
          "answer": "what he says; understood antecedent — 5. Relative antecedents, attraction, and prefixes"
        },
        {
          "prompt": "τῶν ἀγαθῶν ὧν ἔχει",
          "answer": "of the good things which he has; attracted relative — 5. Relative antecedents, attraction, and prefixes"
        },
        {
          "prompt": "ἐκ + ἄγω → ἐξάγω",
          "answer": "ἐκ becomes ἐξ before a vowel — 5. Relative antecedents, attraction, and prefixes"
        },
        {
          "prompt": "σύν + γράφω → συγγράφω",
          "answer": "prefix nasal assimilates before a velar — 5. Relative antecedents, attraction, and prefixes"
        },
        {
          "prompt": "σύν + βάλλω → συμβάλλω",
          "answer": "prefix nasal assimilates before a labial — 5. Relative antecedents, attraction, and prefixes"
        },
        {
          "prompt": "κατά + ἵστημι → καθίστημι",
          "answer": "elision and aspiration at the compound boundary — 5. Relative antecedents, attraction, and prefixes"
        }
      ]
    },
